fn main() {
    let number = 6;
    if number % 4 == 0 {
        println!("divides by 4");
    } else if number % 3 == 0 {
        println!("divides by 3");
    } else if number % 2 == 0 {
        println!("divides by 2");
    } else {
        println!("none of them");
    }
}

fn main() {
    let cold = true;
    let temp = if cold {
        5
    } else {
        25
    };
    println!("temp = {temp}");
}

fn main() {
    let number = 3;
    if number {
        println!("three");
    }
}
